import {canVisitStep,selectSearchOption} from './search-journey.js';
let searchRevision=0;
let currentArchetype;
let currentSearch;
let currentReport;
let guideStep=0;
const selection={};
const $=s=>document.querySelector(s);
async function post(url,data){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(result.error||'Service unavailable');return result;}
function el(tag,text,cls){const node=document.createElement(tag);node.textContent=text;if(cls)node.className=cls;return node;}
function section(card,title,items){
 if(!Array.isArray(items)||!items.length)return;
 card.append(el('h4',title,'profile-section-title'));
 const list=el('ul','','profile-highlights');items.forEach(item=>list.append(el('li',item)));card.append(list);
}
const niches={
 'Market makers & prop trading':{hint:'Electronic trading, liquidity and quantitative firms',skills:['Electronic trading','Market structure','Quantitative systems']},
 'Hedge funds':{hint:'Investment, quantitative and multi-strategy businesses',skills:['Investment management','Risk management','Quantitative research']},
 'Exchanges':{hint:'Trading venues, liquidity and market infrastructure',skills:['Trading systems','Market structure','Operational resilience']},
 'Digital assets':{hint:'Custody, tokenisation and institutional adoption',skills:['Digital asset infrastructure','Institutional adoption','Risk management']},
 'Payments':{hint:'Money movement, acquiring and payment infrastructure',skills:['Payment infrastructure','Commercial partnerships','Operational resilience']},
 'Fintech':{hint:'Financial technology built for the next stage of growth',skills:['Financial technology','Platform scale','Regulated environments']},
 'Financial institutions':{hint:'Financial institutions, investment and wealth',skills:['Financial services','Risk management','Business transformation']},
 'AI infrastructure for finance':{hint:'AI, data and infrastructure for financial markets',skills:['Financial markets','Machine learning infrastructure','Platform scale']}
};
const functions={
 'Trading & investment':{roles:['Head of Trading','Head of Market Making','Head of Quantitative Research','Portfolio Manager','Principal Quantitative Engineer'],mandate:'Build the trading or investment capability your mandate requires.',pillars:[['Domain judgement','Define the strategies, markets and decision rights relevant to the role.'],['Research and execution','Connect research quality, execution and measurable business outcomes.'],['Risk discipline','Establish clear controls, limits and accountability.']]},
 'AI & data':{roles:['Chief AI Officer','Head of AI','Head of Data','Principal Machine Learning Engineer'],mandate:'Connect AI and data capability to a defined financial markets use case.',pillars:[['Use-case discipline','Set the problem, evidence standard and success criteria.'],['Technical depth','Validate AI, data and infrastructure capability against the mandate.'],['Controlled delivery','Build an accountable path from research to reliable deployment.']]},
 'Technology & engineering':{roles:['Chief Technology Officer','VP Engineering','Head of Engineering','Chief Information Security Officer'],mandate:'Build the technical foundations for the next stage of growth.',pillars:[['Architecture that scales','Set a platform direction that supports the commercial roadmap.'],['Teams that deliver','Develop engineering leadership and a clear delivery rhythm.'],['Resilience by design','Balance speed, security and operational reliability.']]},
 'Commercial & growth':{roles:['Chief Revenue Officer','Chief Commercial Officer','VP Sales','Head of Business Development'],mandate:'Turn market opportunity into a repeatable commercial engine.',pillars:[['Market focus','Identify the segments and partnerships that deserve investment.'],['Commercial execution','Bring structure to pipeline, sales leadership and accountability.'],['Durable growth','Connect revenue ambitions with customer value and retention.']]},
 'Product & strategy':{roles:['Chief Product Officer','VP Product','Head of Product','Head of Strategy'],mandate:'Connect customer needs, product choices and commercial ambition.',pillars:[['Product direction','Translate market insight into a focused roadmap.'],['Prioritisation','Make deliberate choices about what to build and why.'],['Cross-functional leadership','Align product, engineering and commercial teams.']]},
 'Risk & compliance':{roles:['Chief Risk Officer','Chief Compliance Officer','Head of Compliance','Head of Financial Crime'],mandate:'Enable growth with clear risk ownership and credible controls.',pillars:[['Regulatory judgement','Navigate the requirements relevant to your business and markets.'],['Practical controls','Build a proportionate operating framework.'],['Leadership confidence','Make risk decisions clear to the board and the business.']]},
 'Operations & finance':{roles:['Chief Operating Officer','Chief Financial Officer','Head of Operations','Finance Director'],mandate:'Create the operating discipline to support your next stage.',pillars:[['Operating clarity','Establish ownership, cadence and decision-making.'],['Financial discipline','Connect resources and investment to business priorities.'],['Execution at scale','Strengthen processes as the organisation grows.']]},
 'Executive leadership':{roles:['Chief Executive Officer','Managing Director','General Manager','Chief People Officer'],mandate:'Set the direction and build the leadership capacity to deliver it.',pillars:[['Strategic direction','Turn an ambitious vision into clear priorities.'],['Leadership depth','Build an accountable and aligned senior team.'],['Business impact','Connect culture, execution and commercial outcomes.']]}
};
const markets=['London','United Kingdom','Europe','New York','Chicago','United States','Dubai','Abu Dhabi','Singapore','Hong Kong','Global / location flexible'];
function optionButton(title,hint,handler,selected=false){const button=el('button','','choice');button.type='button';button.setAttribute('aria-pressed',String(selected));button.append(el('strong',title));if(hint)button.append(el('small',hint));button.addEventListener('click',()=>{button.setAttribute('aria-pressed','true');handler();});return button;}
function invalidateSearch(){
 searchRevision++;currentSearch=null;currentReport=null;currentArchetype=null;
 $('#results').hidden=true;$('#market-brief').hidden=true;$('#search-status').textContent='';$('#search-submit').disabled=false;
}
function jumpToStep(step){
 if(!canVisitStep(selection,step,functions))return;
 invalidateSearch();guideStep=step;drawGuide();$('#search-title').focus({preventScroll:true});
}
function advance(key,value){
 const next=selectSearchOption(selection,key,value,functions);
 Object.keys(selection).forEach(name=>delete selection[name]);Object.assign(selection,next);
 invalidateSearch();guideStep=key==='niche'?1:key==='function'?2:3;drawGuide();
}

function drawGuide(){
 $('#search-form').dataset.stage=String(guideStep);
 const titles=['Choose your sector.','Choose your specialism.','Select the closest role.','Set the location.'];
 const intros=['Choose your niche. We’ll help you pinpoint the leadership your business needs.','Choose the specialism at the heart of your next hire.','Choose a starting point. We’ll refine the exact title and scope with you.','Choose the closest market. Location and working arrangements can be refined on a call.'];
 $('#search-title').textContent=titles[guideStep];$('#guide-intro').textContent=intros[guideStep];
 document.querySelectorAll('.journey li').forEach((item,i)=>{
  const keys=['niche','function','role','location'],labels=['Niche','Specialism','Role','Location'];
  const button=item.querySelector('button'),value=selection[keys[i]];
  item.className=i===guideStep?'active':value?'complete':'';
  button.disabled=!canVisitStep(selection,i,functions);button.setAttribute('aria-label',labels[i]+(value?': '+value:''));
  item.querySelector('.journey-value').textContent=value||['Choose a niche','Choose a specialism','Choose a role','Choose a location'][i];
  if(i===guideStep)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');
 });
 const panel=$('#choice-panel');panel.replaceChildren();const choices=el('div','','choice-grid');
 if(guideStep===0)Object.entries(niches).forEach(([key,value])=>choices.append(optionButton(key,value.hint,()=>advance('niche',key),selection.niche===key)));
 if(guideStep===1)Object.entries(functions).forEach(([key,value])=>choices.append(optionButton(key,value.roles.slice(0,2).join(' · '),()=>advance('function',key),selection.function===key)));
 if(guideStep===2){
  const label=el('label','Find a role in the suggested list');const filter=el('input');filter.type='search';filter.placeholder='Search titles, e.g. CTO or Head of Product';label.append(filter);panel.append(label);
  const populate=()=>{choices.replaceChildren();const query=filter.value.toLowerCase().trim();const roles=query?Object.values(functions).flatMap(value=>value.roles).filter(role=>(role.split(' ').map(w=>w[0]).join('').toLowerCase()===query||role.toLowerCase().split(/\s+/).some((_,i,words)=>words.slice(i).join(' ').startsWith(query)))):functions[selection.function].roles;
   roles.forEach(role=>choices.append(optionButton(role,'Explore this target profile ',()=>advance('role',role),selection.role===role)));if(!roles.length)choices.append(el('p','No listed title matches. Enter your exact role below.'));};
  filter.addEventListener('input',populate);populate();
  const customLabel=el('label','Enter another role');const custom=el('input');custom.maxLength=100;custom.placeholder='e.g. Director of Derivatives Sales';custom.value=selection.customRole?selection.role:'';customLabel.append(custom);const use=el('button','Use this role','text-button');use.type='button';use.addEventListener('click',()=>{if(custom.value.trim().length<3){custom.setCustomValidity('Enter a role with at least three characters.');custom.reportValidity();return;}advance('customRole',custom.value);});custom.addEventListener('input',()=>custom.setCustomValidity(''));panel.append(customLabel,use);
 }
 if(guideStep===3)markets.forEach(market=>{const button=optionButton(market,'',()=>advance('location',market));button.setAttribute('aria-pressed',String(selection.location===market));choices.append(button);});
 panel.append(choices);
 if(guideStep===3&&selection.location){const label=el('label','Job description or key requirements (optional)');const jd=el('textarea');jd.maxLength=4000;jd.rows=5;jd.placeholder='Products, client types, skills, seniority and what success looks like. Remove names, contact details and confidential information.';jd.value=selection.jobDescription||'';jd.addEventListener('input',()=>{selection.jobDescription=jd.value;invalidateSearch();$('#search-submit').textContent='Review requirements';$('#requirements-review').hidden=true;});label.append(jd);panel.append(label,el('p','Role requirements may be processed by our AI service to create a fictional example CV. Do not paste personal or confidential information.','guide-note'));}
 $('#requirements-review').hidden=true;$('#search-submit').textContent='Review requirements';$('#guide-back').hidden=guideStep===0;$('#guide-context').textContent=[selection.niche,guideStep>1?selection.function:null,guideStep>2?selection.role:null].filter(Boolean).join(' / ');$('#search-submit').hidden=guideStep!==3||!selection.location;
}
$('#guide-back').addEventListener('click',()=>jumpToStep(Math.max(0,guideStep-1)));
document.querySelectorAll('.journey button').forEach(button=>button.addEventListener('click',()=>jumpToStep(Number(button.dataset.step))));
function blueprint(input,spec){
 const article=el('article','','blueprint candidate-cv');
 const top=el('div','','blueprint-top');top.append(el('span',spec.niche+' / '+input.location,'step'),el('span','Target profile','blueprint-label'));article.append(top);
 const core=el('div','','blueprint-core');const story=el('div','','blueprint-story');story.append(el('h3',spec.role),el('p',spec.professionalSummary,'cv-summary'),el('p',spec.experienceYears+' years of relevant experience','cv-experience'),el('p',spec.leadershipScope,'cv-scope'));
 const chips=el('div','','chips');spec.focus.forEach(skill=>chips.append(el('span',skill)));story.append(chips,el('h4','Markets & specialisms','cv-sidebar-heading'),el('p',spec.markets.join(' · '),'cv-sector'),el('h4','Technology & methods','cv-sidebar-heading'));const tools=el('ul','','cv-tools');spec.technologies.forEach(tool=>tools.append(el('li',tool)));story.append(tools,el('p',spec.baseFocus,'target-salary'));
 const call=el('a','Discuss this profile ','button');call.href='https://meetings-eu1.hubspot.com/sam-w/new-client-hiring-briefing-clone';call.target='_blank';call.rel='noopener noreferrer';story.append(call);core.append(story);
 const history=el('div','','cv-history');history.append(el('h4','Career progression','cv-section-heading'));
 spec.careerHistory.forEach(stage=>{const item=el('section','','cv-role');item.append(el('span',stage.period+' / '+stage.stage,'step'),el('h4',stage.title),el('p',stage.environment,'cv-environment'));const list=el('ul','','profile-highlights');stage.responsibilities.forEach(line=>list.append(el('li',line)));item.append(list);history.append(item);});
 const figures=el('section','','cv-figures');figures.append(el('h4','Example results & scope','cv-section-heading'),el('p',spec.metricsDisclosure,'cv-metrics-note'));const metrics=el('div','','cv-metrics');spec.metrics.forEach(metric=>{const card=el('article','','cv-metric');card.append(el('h5',metric.label),el('p',metric.value,'cv-metric-value'),el('p',metric.context,'cv-metric-context'));metrics.append(card);});figures.append(metrics);history.append(figures);history.append(el('h4','Achievement examples','cv-section-heading'));spec.achievementExamples.forEach(item=>{const row=el('div','','capability');const text=el('div');text.append(el('h4',item.area),el('p',item.example));row.append(text);history.append(row);});core.append(history);article.append(core);
 const question=el('div','','brief-question');question.append(el('span','Your first-year mandate','step'),el('p',spec.question));article.append(question);return article;
}
$('#search-form').addEventListener('submit',async event=>{
 event.preventDefault();if(guideStep!==3||!selection.location||!canVisitStep(selection,3,functions))return;
 const review=$('#requirements-review');if(review.hidden){review.replaceChildren(el('h3','Confirm your search'),el('p',[selection.niche,selection.function,selection.role,selection.location].join(' / ')),el('p',selection.jobDescription||'No additional requirements.'),el('p','Senior mandate: US$150,000+ annual base. The preview is a fictional example CV; actual candidate interest and availability need confirmation.'));review.hidden=false;$('#search-submit').textContent='Confirm and search';return;}
 const revision=++searchRevision;
 const button=$('#search-submit');button.disabled=true;$('#search-status').textContent='Building your target profile and checking relevant, shareable CRM profiles…';$('#results').hidden=true;$('#market-brief').hidden=true;currentSearch=null;currentReport=null;currentArchetype=null;
 try{
  const input={role:selection.role,location:selection.location,niche:selection.niche,function:selection.function,skills:niches[selection.niche].skills.join(', '),jobDescription:selection.jobDescription||''};
  const data=await post('/api/search',input);if(revision!==searchRevision)return;currentArchetype=data.profiles?.[0];if(!currentArchetype){$('#search-status').textContent=data.message;return;}if(!currentArchetype||currentArchetype.kind!=='synthetic'||!Array.isArray(currentArchetype.careerHistory))throw Error('The saved profile is unavailable. Please book a briefing.');currentSearch={...input,skills:currentArchetype.focus.join(', ')};if(data.crmDiagnostic)console.warn('Recruit CRM connection:',data.crmDiagnostic);const grid=$('#profile-grid');grid.replaceChildren();
  $('#result-tag').textContent='Example CV · Hypothetical career history';
  $('#result-message').textContent=data.crmStatus==='searched'?'Your brief has been checked against our confidential CRM. Speak with us to confirm candidate fit, availability and interest.':data.crmStatus==='unavailable'?'Your example CV is ready. The private CRM check is temporarily unavailable.':'Your example CV is ready. A briefing can begin a confidential candidate search.';
  grid.append(blueprint(input,currentArchetype));
  buildMarketBrief(input,data.crmStatus,currentArchetype);grid.classList.toggle('blueprint-grid',data.synthetic);$('#results').hidden=false;$('#search-status').textContent='Your search preview is ready.';$('#results').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(error){if(revision===searchRevision)$('#search-status').textContent=error.message;}finally{if(revision===searchRevision)button.disabled=false;}
});
drawGuide();
const reportLogo='data:image/svg+xml;base64,';
const salaryGuide='https://www.spearpointsearch.com/resources/salary-guide';
const sectorPages={
 'Exchanges':'https://www.spearpointsearch.com/exchanges-venues-executive-search',
 'Digital assets':'https://www.spearpointsearch.com/digital-assets-crypto-executive-search',
 'Payments':'https://www.spearpointsearch.com/fintech-payments-executive-search',
 'Fintech':'https://www.spearpointsearch.com/fintech-payments-executive-search'
};
const pools={
 'Market makers & prop trading':['Electronic market makers','Proprietary trading firms','Trading infrastructure and quantitative technology teams'],
 'Hedge funds':['Investment and multi-strategy funds','Quantitative investment businesses','Relevant trading and financial technology teams'],
 'Exchanges':['Trading venues and exchange infrastructure','Market makers and liquidity providers','Institutional brokerage and trading technology'],
 'Digital assets':['Custody and digital asset infrastructure','Institutional financial services with digital asset teams','Exchanges and prime brokerage'],
 'Payments':['Payment processors and acquiring platforms','Banks with payments infrastructure teams','Financial technology and embedded finance businesses'],
 'Fintech':['Financial technology platforms','Banks and financial infrastructure businesses','Adjacent software businesses with relevant operating complexity'],
 'Financial institutions':['Banks and investment businesses','Financial market infrastructure','Financial technology businesses with relevant regulatory exposure'],
 'AI infrastructure for finance':['AI and data businesses serving financial markets','Quantitative research and financial engineering teams','Financial infrastructure platforms with relevant AI capability']
};
function buildMarketBrief(input,crmStatus,spec){
const niche=selection.niche;
 currentReport={role:input.role,location:input.location,niche,function:selection.function,prepared:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}),crmStatus,
 sections:[
  {title:'Salary guide',eyebrow:'3.2 / Compensation',intro:`Benchmark ${input.role} in ${input.location} against the scope of your mandate.`,items:['Use the Spearpoint Compensation Guide as a starting point, then confirm that sector, function, seniority and city match your brief.','Compare base salary, target bonus and long-term incentives separately. Equity or token arrangements need their own valuation and terms.','An exact salary band is not reproduced here. Where the selected role or market is absent, request a tailored benchmark rather than substitute an unrelated figure.'],source:{label:'Spearpoint Compensation Guide · 2026 / 2027 edition, September 2026',url:salaryGuide},action:'Open the salary guide ',note:'Source checked 21 October 2026. The guide uses researched ranges and location indices; its percentiles are not a large-sample survey statistic.'},
  {title:'Candidate landscape',eyebrow:'3.3 / Search direction',intro:`Where we would start exploring a ${niche.toLowerCase()} leadership search.`,items:pools[niche].map(pool=>`Potential talent pool: ${pool}.`),source:sectorPages[niche]?{label:'Spearpoint sector search overview',url:sectorPages[niche]}:null,action:'Explore the sector ',note:'These are proposed sourcing directions, not measured talent supply, candidate counts or evidence of availability. Validate transferable experience against the mandate.'},
  {title:'Talent insight',eyebrow:'3.4 / Shape the mandate',intro:spec.mandate,items:[...spec.pillars.map(([title,description])=>`${title}: ${description}`),'Before launching: agree the first-year outcomes, essential experience, reporting line and the flexibility of the package.'],source:null,note:'Planning guidance based on your selected function and niche. A consultant should validate it against your business stage and exact role.'}
 ]};
 $('#market-context').textContent=`${input.role} / ${niche} / ${input.location}`;
 const container=$('#market-sections');container.replaceChildren();
 currentReport.sections.forEach(part=>{
  const card=el('article','','insight-card');card.append(el('span',part.eyebrow,'step'),el('h3',part.title),el('p',part.intro,'insight-intro'));section(card,'What to consider',part.items);
  if(part.source){const link=el('a',part.action,'insight-source');link.href=part.source.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link,el('p',part.source.label,'source-caption'));}
  card.append(el('p',part.note,'insight-note'));container.append(card);
 });
 $('#market-brief').hidden=false;$('#download-status').textContent='';
}
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
$('#download-brief').addEventListener('click',()=>{
 if(!currentReport)return;const r=currentReport,e=escapeHtml;
 const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spearpoint hiring market brief . ${e(r.role)}</title><style>:root{--ink:#242424;--muted:rgba(36,36,36,.7);--rule:rgba(36,36,36,.15)}*{box-sizing:border-box}body{font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","Helvetica Neue",sans-serif;color:var(--ink);background:#fff;max-width:1040px;padding:40px;margin:auto}h1,h2{font-family:"GT Canon",Georgia,"Times New Roman",serif;font-weight:400;letter-spacing:0}h1{font-size:53px;line-height:1.2}h2{font-size:32px;line-height:1.3}header{border-top:1px solid var(--ink);border-bottom:1px solid var(--rule);padding:24px 0 32px}.brand{font:600 25px/1.3 Georgia,serif;text-align:right}section{padding:32px 0;border-bottom:1px solid var(--rule)}p{max-width:640px}a{color:var(--ink)}.note,footer{font:12px/1.5 "Geist Mono",ui-monospace,Menlo,Consolas,monospace;color:#48586e}li{margin:16px 0;max-width:640px}.call{padding:32px;background:#f3f3f3} @media print{body{padding:0}a{color:inherit}section{break-inside:avoid}}@media(max-width:600px){body{padding:24px}h1{font-size:36px}}</style></head><body><header><p class="brand"><img src="${reportLogo}" width="235" height="29" alt="Spearpoint"></p><p>Hiring market brief</p><h1>${e(r.role)}</h1><p>${e(r.niche)} · ${e(r.location)} · Prepared ${e(r.prepared)}</p><p class="note">Search-planning guidance. No candidate identities, availability claims or unsourced compensation figures are included.</p></header>${r.sections.map(part=>`<section><p class="note">${e(part.eyebrow)}</p><h2>${e(part.title)}</h2><p>${e(part.intro)}</p><ul>${part.items.map(item=>`<li>${e(item)}</li>`).join('')}</ul>${part.source?`<p><a href="${e(part.source.url)}">${e(part.source.label)}</a></p>`:''}<p class="note">${e(part.note)}</p></section>`).join('')}<section class="call"><h2>Turn the brief into a focused search.</h2><p>Discuss the mandate, validate the market and agree your next move.</p><a href="https://meetings-eu1.hubspot.com/sam-w/new-client-hiring-briefing-clone">Book your hiring briefing </a></section><footer><p>This brief is generated from your selected niche, function, role and market. Candidate landscape and talent insight are planning recommendations, not a live market survey. Salary guidance links to the published Spearpoint source; no specific role/market band has been independently verified here.</p><p>Open this file in a browser to read it, or use Print → Save as PDF to keep a PDF copy.</p></footer></body></html>`;
 const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const link=el('a');link.href=url;link.download=`spearpoint-hiring-brief-${r.role.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.html`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('#download-status').textContent='Your brief download has started. Open it in a browser to read it or print it as a PDF.';
});
$('#request-report').addEventListener('click',()=>{
 if(!currentReport)return;$('#brief-details').open=true;$('#brief-form [name=notes]').value=`Please follow up with a tailored hiring market brief for ${currentReport.role} in ${currentReport.location}, within ${currentReport.niche}. I would like to discuss salary benchmarking, candidate landscape and talent insight.`;$('#brief-details').scrollIntoView({behavior:'smooth',block:'start'});$('#brief-form [name=name]').focus({preventScroll:true});
});
$('#brief-form').addEventListener('submit',async event=>{
 event.preventDefault();if(!currentSearch)return;const button=event.target.querySelector('button');button.disabled=true;$('#brief-status').textContent='Saving your briefing request…';
 try{const data=Object.fromEntries(new FormData(event.target));const result=await post('/api/brief',{...currentSearch,...data,notes:`${data.notes||'Hiring briefing request'}\nSearch context: ${currentReport?.niche||selection.niche}; ${currentReport?.function||selection.function}. Report version: 2026-10-21.`,consent:data.consent==='on'});$('#brief-status').textContent=`${result.message} Reference: ${result.reference}`;event.target.reset();}catch(error){$('#brief-status').textContent=error.message;}finally{button.disabled=false;}
});
